//! Verifies natively an ownership proof generated by the WASM build.
//!
//! WASM and native provers must produce the same Fiat-Shamir transcript, so a browser
//! proof has to verify here and fail with any other public input. Opt-in: run the browser
//! spec `web/walletkit/tests/staging-ownership.spec.ts` with `WALLETKIT_STAGING_PROOF` set to
//! an output path, then run this test with the same variable. Without it the test is a no-op.

use std::str::FromStr;

use eyre::{bail, eyre, Result, WrapErr as _};
use world_id_core::primitives::{FieldElement, OwnershipProof};
use world_id_proof::{
    artifacts::embedded::EmbeddedZkArtifacts, ownership_proof::verify_ownership_proof,
};

fn field(json: &serde_json::Value, key: &str) -> Result<FieldElement> {
    let value = json[key].as_str().ok_or_else(|| eyre!("missing `{key}`"))?;
    FieldElement::from_str(value).map_err(|e| eyre!("invalid `{key}`: {e}"))
}

/// The same element with its last byte flipped, still below the modulus.
fn tampered(value: FieldElement) -> Result<FieldElement> {
    let mut bytes = value.to_be_bytes();
    bytes[31] ^= 0x01;
    FieldElement::from_be_bytes(&bytes).map_err(|e| eyre!("tampering failed: {e}"))
}

#[test]
fn wasm_ownership_proof_verifies_natively_and_rejects_other_inputs() -> Result<()> {
    let Some(path) = std::env::var_os("WALLETKIT_STAGING_PROOF") else {
        eprintln!("skipped: set WALLETKIT_STAGING_PROOF to a proof written by the browser spec");
        return Ok(());
    };
    let json: serde_json::Value = serde_json::from_slice(
        &std::fs::read(&path).wrap_err("reading the browser proof")?,
    )?;
    let bytes = hex::decode(
        json["proof"]
            .as_str()
            .ok_or_else(|| eyre!("missing `proof`"))?,
    )?;
    let proof: OwnershipProof =
        ciborium::from_reader(bytes.as_slice()).wrap_err("decoding the CBOR proof")?;
    let (sub, nonce, context) = (
        field(&json, "sub")?,
        field(&json, "nonce")?,
        field(&json, "context")?,
    );
    let artifacts = EmbeddedZkArtifacts;

    verify_ownership_proof(&proof, nonce, sub, context, &artifacts)
        .wrap_err("the WASM proof must verify natively")?;
    for (input, result) in [
        (
            "context",
            verify_ownership_proof(&proof, nonce, sub, tampered(context)?, &artifacts),
        ),
        (
            "nonce",
            verify_ownership_proof(&proof, tampered(nonce)?, sub, context, &artifacts),
        ),
        (
            "sub",
            verify_ownership_proof(&proof, nonce, tampered(sub)?, context, &artifacts),
        ),
    ] {
        if result.is_ok() {
            bail!("a proof with a different {input} must not verify");
        }
    }
    Ok(())
}
